INSERT INTO tournaments (year, host, winner, runner_up) VALUES
  (1991, 'China', 'United States', 'Norway'),
  (1995, 'Sweden', 'Norway', 'Germany'),
  (1999, 'United States', 'United States', 'China'),
  (2003, 'United States', 'Germany', 'Sweden'),
  (2007, 'China', 'Germany', 'Brazil'),
  (2011, 'Germany', 'Japan', 'United States'),
  (2015, 'Canada', 'United States', 'Japan'),
  (2019, 'France', 'United States', 'Netherlands'),
  (2023, 'Australia / New Zealand', 'Spain', 'England');
INSERT INTO teams (code, name, confederation, coach_2023, summary) VALUES
  ('BRA', 'Brazil', 'CONMEBOL', 'Pia Sundhage', 'Brazil have played at all nine Women''s World Cups. They finished runners-up in 2007 and third in 1999, and Marta holds the record for most goals at a Women''s World Cup with 17.'),
  ('USA', 'United States', 'CONCACAF', 'Vlatko Andonovski', 'The most successful team in the tournament''s history, with four titles (1991, 1999, 2015 and 2019). In 2023 they were knocked out by Sweden on penalties in the round of 16, their earliest exit.'),
  ('GER', 'Germany', 'UEFA', 'Martina Voss-Tecklenburg', 'Two-time champions (2003 and 2007) and runners-up in 1995. They won the 2007 title without conceding a goal, but went out in the group stage in 2023 for the first time.'),
  ('NOR', 'Norway', 'UEFA', 'Hege Riise', 'Champions in 1995 and runners-up in the very first tournament in 1991. They also reached the semi-finals in 1999 and 2007, but were eliminated in the group stage in 2023.'),
  ('JPN', 'Japan', 'AFC', 'Futoshi Ikeda', 'Champions in 2011, becoming the first Asian team to win a senior FIFA World Cup, after beating the United States on penalties in the final. Runners-up in 2015 and quarter-finalists in 2023.'),
  ('ESP', 'Spain', 'UEFA', 'Jorge Vilda', 'Spain first qualified in 2015 and became world champions in 2023 in only their third appearance, beating England 1-0 in the final.');
